                        inset 0 0 20px rgba(108, 142, 239, 0.1);
        }

        .state.validation {
            background: linear-gradient(145deg, #5a4a2d, #3d321e);
            border: 4px solid #efc86c;
            box-shadow: 0 0 30px rgba(239, 200, 108, 0.4),
                        inset 0 0 20px rgba(239, 200, 108, 0.1);
        }

        .state.final {
            background: linear-gradient(145deg, #4a2d5a, #321e3d);
            border: 4px solid #c86cef;
            box-shadow: 0 0 30px rgba(200, 108, 239, 0.4),
                        inset 0 0 20px rgba(200, 108, 239, 0.1);
        }

        .state-number {
            font-size: 0.9rem;
            font-weight: bold;
            opacity: 0.7;
            margin-bottom: 5px;
        }

        .state-name {
            font-size: 1rem;
            font-weight: 600;
            padding: 0 10px;
        }

        .state-artifact {
            font-size: 0.75rem;
            opacity: 0.6;
            margin-top: 8px;
            font-style: italic;
        }

        /* Arrow/Transition styling */
        .transition-arrow {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 5px;
        }

        .arrow-line {
            width: 80px;
            height: 4px;
            background: linear-gradient(90deg, #4ecca3, #6c8eef);
            position: relative;
        }

        .arrow-line::after {
            content: '';
            position: absolute;
            right: -8px;
            top: -6px;
            border: 8px solid transparent;
            border-left: 12px solid #6c8eef;
        }

        .arrow-down {
            width: 4px;
            height: 60px;
            background: linear-gradient(180deg, #6c8eef, #efc86c);
            position: relative;
        }

        .arrow-down::after {
            content: '';
            position: absolute;
            bottom: -8px;
            left: -6px;
            border: 8px solid transparent;
            border-top: 12px solid #efc86c;
        }

        .event-label {
            font-size: 0.75rem;
            color: #4ecca3;
            background: rgba(78, 204, 163, 0.15);
            padding: 4px 10px;
            border-radius: 12px;
            border: 1px solid rgba(78, 204, 163, 0.3);
        }

        /* Vertical connector */
        .vertical-connector {
            display: flex;
            flex-direction: column;
            align-items: center;
        }

        /* Legend */
        .legend {
            margin-top: 50px;
            display: flex;
            justify-content: center;
            gap: 40px;
            flex-wrap: wrap;
        }

        .legend-item {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .legend-dot {
            width: 20px;
            height: 20px;
            border-radius: 50%;
            border: 2px solid;
        }

        .legend-dot.initial { border-color: #4ecca3; background: rgba(78, 204, 163, 0.3); }
        .legend-dot.processing { border-color: #6c8eef; background: rgba(108, 142, 239, 0.3); }
        .legend-dot.validation { border-color: #efc86c; background: rgba(239, 200, 108, 0.3); }
        .legend-dot.final { border-color: #c86cef; background: rgba(200, 108, 239, 0.3); }

        .legend-text {
            font-size: 0.9rem;
            color: #a0a0a0;
        }

        /* Key Concepts */
        .concepts {
            margin-top: 60px;
