    <title>Finite State Machine Concept Diagram</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Segoe UI', system-ui, -apple-system, sans-serif;
            background: linear-gradient(135deg, #1a1a2e 0%, #16213e 50%, #0f3460 100%);
            min-height: 100vh;
            padding: 40px 20px;
            color: #e0e0e0;
        }

        .container {
            max-width: 1200px;
            margin: 0 auto;
        }

        h1 {
            text-align: center;
            font-size: 2.5rem;
            margin-bottom: 10px;
            color: #4ecca3;
            text-shadow: 0 0 20px rgba(78, 204, 163, 0.3);
        }

        .subtitle {
            text-align: center;
            font-size: 1.1rem;
            color: #a0a0a0;
            margin-bottom: 50px;
        }

        .fsm-diagram {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 30px;
        }

        /* State node styling */
        .state-row {
            display: flex;
            justify-content: center;
            align-items: center;
            gap: 60px;
            position: relative;
        }

        .state {
            width: 160px;
            height: 160px;
            border-radius: 50%;
            display: flex;
            flex-direction: column;
            align-items: center;
            justify-content: center;
            text-align: center;
            position: relative;
            transition: all 0.3s ease;
            cursor: pointer;
        }

        .state:hover {
            transform: scale(1.08);
        }

        .state.initial {
            background: linear-gradient(145deg, #2d5a4a, #1e3d32);
            border: 4px solid #4ecca3;
            box-shadow: 0 0 30px rgba(78, 204, 163, 0.4),
                        inset 0 0 20px rgba(78, 204, 163, 0.1);
        }

        .state.processing {
            background: linear-gradient(145deg, #3d4a6b, #2a3450);
            border: 4px solid #6c8eef;
            box-shadow: 0 0 30px rgba(108, 142, 239, 0.4),
                        inset 0 0 20px rgba(108, 142, 239, 0.1);
        }

        .state.validation {
            background: linear-gradient(145deg, #5a4a2d, #3d321e);
            border: 4px solid #efc86c;
            box-shadow: 0 0 30px rgba(239, 200, 108, 0.4),
                        inset 0 0 20px rgba(239, 200, 108, 0.1);
        }

        .state.final {
            background: linear-gradient(145deg, #4a2d5a, #321e3d);
            border: 4px solid #c86cef;
            box-shadow: 0 0 30px rgba(200, 108, 239, 0.4),
                        inset 0 0 20px rgba(200, 108, 239, 0.1);
        }

        .state-number {
            font-size: 0.9rem;
            font-weight: bold;
            opacity: 0.7;
            margin-bottom: 5px;
        }

        .state-name {
            font-size: 1rem;
            font-weight: 600;
            padding: 0 10px;
        }

        .state-artifact {
            font-size: 0.75rem;
            opacity: 0.6;
            margin-top: 8px;
            font-style: italic;
        }

        /* Arrow/Transition styling */
        .transition-arrow {
            display: flex;
            flex-direction: column;
            align-items: center;
            gap: 5px;
        }

        .arrow-line {
            width: 80px;
            height: 4px;
            background: linear-gradient(90deg, #4ecca3, #6c8eef);
            position: relative;
        }

        .arrow-line::after {
            content: '';
            position: absolute;
            right: -8px;
            top: -6px;
            border: 8px solid transparent;
            border-left: 12px solid #6c8eef;
